lemma TotalTransfer(balances: map<int, int>, sender: int, recipient: int, amount: int)
  requires sender in balances && recipient in balances && 0 in balances
  requires sender != recipient && sender != 0 && recipient != 0
  ensures Total(balances[sender := balances[sender] - amount - 1]
                        [recipient := balances[recipient] + amount]
                        [0 := balances[0] + 1]) == Total(balances)
{
  var debited := balances[sender := balances[sender] - amount - 1];
  TotalReplace(balances, sender, balances[sender] - amount - 1);
  var credited := debited[recipient := balances[recipient] + amount];
  TotalReplace(debited, recipient, balances[recipient] + amount);
  TotalReplace(credited, 0, balances[0] + 1);
}

